      "id": 1,
      "claim": "Pitman shorthand was invented by Sir Isaac Pitman in the 1830s (first published 1832, widely disseminated by 1837).",
      "evidence": "Historical records of Pitman's \"Stenographic Soundhand\" show first publication in 1832 and the more complete system in 1837, both after 1791.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The Tenth Amendment was drafted and ratified between 1789 and 1791.",
      "evidence": "Congressional records and the ratification dates of the Bill of Rights show the amendment was proposed in 1789 and ratified on December 15, 1791.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "The original drafting and official copies of the Tenth Amendment were produced in standard longhand manuscript and printed type, with no contemporaneous evidence of shorthand use.",
      "evidence": "Archival documents (the original engrossed copies of the Bill of Rights) are handwritten in cursive script; contemporaneous notes from the Constitutional Convention and the First Congress contain no references to shorthand, and shorthand was not a common legislative tool in the 18th‑century United States.",
      "weight": 0.40,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Therefore the Tenth Amendment was not written using Pitman shorthand.",
      "evidence": "Given that Pitman shorthand did not exist at the time of drafting (step 1) and that the amendment’s original documents were created in longhand (step 3), it could not have been written in that system.",
      "weight": 0.10,
      "depends_on": [3]
    }
  ],
  "answer": "No",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "Yes",
      "reason_rejected": "Even if later transcriptions existed, the question concerns the original writing of the amendment; there is no historical record of any original or official version being produced in Pitman shorthand."
    }
  ]
